        13'd1006 : uw <= 92'h00000000020000004039E00;   // yes -- vector 7
        13'd1007 : uw <= 92'h00000000020000004039E0A;   // the condition
        13'd1008 : uw <= 92'h0000000802000000403F101;   // not taken, and nothing happens
        13'd1009 : uw <= 92'h0000000402000000403F200;   // the operand word the handler may want, which this does not read
        13'd1010 : uw <= 92'h00000000020000004039E0A;   // the condition
        13'd1011 : uw <= 92'h0000000802000000403F401;   // not taken, and nothing happens
        13'd1012 : uw <= 92'h0000000402000000403F500;   // the operand word the handler may want, which this does not read
        13'd1013 : uw <= 92'h0000000402000000403F600;   // the operand word the handler may want, which this does not read
        13'd1014 : uw <= 92'h00000000020000004039E0A;   // the condition
        13'd1015 : uw <= 92'h0000000802000000403F801;   // not taken, and nothing happens
        13'd1016 : uw <= 92'h00012000020800C8403F900;   // vector 9
        13'd1017 : uw <= 92'h0000000002180100403FA00;   // the instruction that was traced
        13'd1018 : uw <= 92'h00000000021000704038300;   // and the frame carries the address of the next one
        13'd1019 : uw <= 92'h0000000001200078403FC00;   // a copy of the status register as it was, before anything moves
        13'd1020 : uw <= 92'h00000000014BF678403FD00;   // the mask goes up to this level -- UM 6.1 step one, second half
        13'd1021 : uw <= 92'h0200000002000001824007A;   // the acknowledge cycle: CPU space, type $F, the level on A3-A1
        13'd1022 : uw <= 92'h00000000020000004040182;   // ... or nobody answered at all
        13'd1023 : uw <= 92'h00000000020800F84040200;   // the device supplied a vector number
        13'd1024 : uw <= 92'h00000000020800F04040200;   // the autovector for this level -- UM table 6-1, vectors 25 to 31
        13'd1025 : uw <= 92'h00030000020800C84040200;   // a spurious interrupt -- vector 24
        13'd1026 : uw <= 92'h0000000002100070404045A;   // the frame carries the address of the next instruction -- UM table 6-5
        13'd1027 : uw <= 92'h00000000014B80784037700;   // supervisor, and no tracing of the handler -- UM 6.1 step one again; the copy the frame carries was taken above
        13'd1028 : uw <= 92'h00000000014B80784040500;   // supervisor, and no tracing of the handler -- UM 6.1 step one
        13'd1029 : uw <= 92'h00000000025000B04040600;   // the master stack: M is still set, so this is MSP
        13'd1030 : uw <= 92'h000000000250D0184040700;   // +$06: the format and the vector offset
        13'd1031 : uw <= 92'h00000000020000D27440800;   // ... written there
        13'd1032 : uw <= 92'h000000000250D2184040900;   // +$02: the program counter
        13'd1033 : uw <= 92'h000000000200003C7440A00;   // ... written there
        13'd1034 : uw <= 92'h000000000250D0184040B00;   // +$00: the status register as it was
        13'd1035 : uw <= 92'h000000000200004A7440C00;   // ... written there
        13'd1036 : uw <= 92'h00000000024000184040D00;   // and the master stack pointer is where that frame begins
        13'd1037 : uw <= 92'h00000000014C00784040E00;   // now clear M, which moves the stack from MSP to ISP
        13'd1038 : uw <= 92'h00000000012440484040F00;   // the saved status register again, with S set this time
        13'd1039 : uw <= 92'h00000000025000B04041000;   // the interrupt stack
        13'd1040 : uw <= 92'h000000000250D0184041100;   // +$06: the format and the vector offset
        13'd1041 : uw <= 92'h00200000020000D27441200;   // ... written there
        13'd1042 : uw <= 92'h000000000250D2184041300;   // +$02: the program counter
        13'd1043 : uw <= 92'h000000000200003C7441400;   // ... written there
        13'd1044 : uw <= 92'h000000000250D0184041500;   // +$00: the status register as it was
        13'd1045 : uw <= 92'h000000000200004A7441600;   // ... written there
        13'd1046 : uw <= 92'h00000000024000184037F00;   // and the interrupt stack pointer is where the throwaway begins
        default:      uw <= 92'h00000000020000004039300;   // the illegal entry
      endcase
    end
  end

